import { describe, expect, test } from "vitest"
import { parserPaths, parserProfile } from "../infra/host/parser-plane.ts"
import {
  buildParserPlan,
  probeProfile,
  probeSocketPath,
} from "./isolation-parser-plan.ts"
import type { ParserPlanInput } from "./isolation-parser-plan.ts"

// The installed profile is generated by `host plane` (#818); the test builds it the same way, from
// the plane's own function, so a change to the daemon's profile reaches the plan builder here.
const PATHS = parserPaths("/var/empty/eido", "/var/empty/home")
const DAEMON_PROFILE = parserProfile(PATHS)
const ID = "00112233445566ff"
const PROBE_SOCKET = "/var/empty/eido/parser-run/probe-00112233445566ff.sock"

const INPUT: ParserPlanInput = {
  daemonProfile: DAEMON_PROFILE,
  daemonSocket: PATHS.socket,
  node: "/opt/node/bin/node",
  coreHooks: "/repo/packages/core/src/ts-hooks.ts",
  noNetwork: "/repo/packages/core/src/parsers/no-network.ts",
  brokerEntry: "/repo/scripts/isolation-parser-broker.ts",
  workerEntry: "/repo/scripts/isolation-parser-child.ts",
  id: ID,
}

function planOf(input: ParserPlanInput) {
  const built = buildParserPlan(input)
  if (!built.ok) throw new Error(built.error)
  return built.plan
}

describe("buildParserPlan", () => {
  test("names the _eidoparse user and a probe socket beside the production socket", () => {
    const plan = planOf(INPUT)
    expect(plan.user).toBe("_eidoparse")
    expect(plan.socket).toBe(PROBE_SOCKET)
    expect(plan.brokerSudoArgs.slice(0, 4)).toEqual([
      "-n",
      "-u",
      "_eidoparse",
      "--",
    ])
  })

  test("starts the broker as the daemon does, under sandbox-exec, with the probe socket and worker", () => {
    const { brokerSudoArgs, socket } = planOf(INPUT)
    expect(brokerSudoArgs.slice(4, 6)).toEqual(["/usr/bin/sandbox-exec", "-p"])
    expect(brokerSudoArgs.slice(7)).toEqual([
      "/opt/node/bin/node",
      "--disable-warning=ExperimentalWarning",
      "--import",
      "/repo/packages/core/src/ts-hooks.ts",
      "--import",
      "/repo/packages/core/src/parsers/no-network.ts",
      "/repo/scripts/isolation-parser-broker.ts",
      "--socket",
      socket,
      "--worker",
      "/repo/scripts/isolation-parser-child.ts",
    ])
  })

  test("has one sandbox-exec, around the broker alone: no -f profile file and no wrapped child", () => {
    const { brokerSudoArgs } = planOf(INPUT)
    expect(
      brokerSudoArgs.filter((arg) => arg.endsWith("sandbox-exec"))
    ).toHaveLength(1)
    expect(brokerSudoArgs).not.toContain("-f")
    // The parse child's entry is the broker's argument, never a command of its own.
    expect(brokerSudoArgs.at(-2)).toBe("--worker")
  })

  test("runs the broker under the installed profile with only the socket swapped", () => {
    const profile = planOf(INPUT).brokerSudoArgs[6]
    expect(profile).toBe(DAEMON_PROFILE.replace(PATHS.socket, PROBE_SOCKET))
    expect(profile).toContain("(deny network*)")
    expect(profile).toContain(`(path-literal "${PROBE_SOCKET}")`)
    expect(profile).not.toContain(PATHS.socket)
  })

  test.each([
    ["too short", "0011"],
    ["not hex", "zz112233445566ff"],
    ["upper case", "00112233445566FF"],
    ["a path", "../../etc/passwd0"],
  ])("refuses an id that is %s", (_why, id) => {
    expect(buildParserPlan({ ...INPUT, id })).toEqual({
      ok: false,
      error: "the probe id must be 16 hex characters",
    })
  })

  test("refuses a socket path that would not fit sockaddr_un", () => {
    const long = `/var/empty/${"d".repeat(90)}/parser.sock`
    const built = buildParserPlan({
      ...INPUT,
      daemonSocket: long,
      daemonProfile: parserProfile({ ...PATHS, socket: long }),
    })
    expect(built.ok).toBe(false)
    if (!built.ok) expect(built.error).toContain("too long")
  })

  test("refuses a profile that does not name the daemon socket", () => {
    expect(
      buildParserPlan({ ...INPUT, daemonSocket: "/var/empty/other.sock" })
    ).toEqual({
      ok: false,
      error:
        "the parser profile does not name /var/empty/other.sock exactly once",
    })
  })
})

describe("probeProfile", () => {
  test("refuses a profile that names the socket twice, since a swap would leave one", () => {
    const twice = `${DAEMON_PROFILE}(allow network-bind (local unix-socket (path-literal "${PATHS.socket}")))\n`
    expect(probeProfile(twice, PATHS.socket, PROBE_SOCKET)).toEqual({
      ok: false,
      error: `the parser profile does not name ${PATHS.socket} exactly once`,
    })
  })

  test("refuses a profile that does not deny the network", () => {
    const open = DAEMON_PROFILE.replace("(deny network*)\n", "")
    expect(probeProfile(open, PATHS.socket, PROBE_SOCKET)).toEqual({
      ok: false,
      error: "the parser profile does not deny the network",
    })
  })
})

describe("probeSocketPath", () => {
  test("sits in the production socket's directory", () => {
    expect(probeSocketPath("/a/b/parser.sock", ID)).toBe(
      "/a/b/probe-00112233445566ff.sock"
    )
  })
})
